            dx = 1
        elif target_x < sx:
            dx = -1
        if target_y > sy:
            dy = 1
        elif target_y < sy:
            dy = -1
        return [dx, dy]

    # Defensive move selection: prioritize known targets
    if env == "territory_control":
        targets = get_field("unclaimed_cells") or get_field("opponent_territory") or []
        if targets:
            best = min(targets, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
            return move_toward(best[0], best[1])
        else:
            return [0,0]

    elif env == "pursuit_evasion":
        role = get_field("self_role", "pursuer")
        if role == "pursuer":
            return move_toward(ox, oy)
        else:
            dx = dy = 0
            if ox >= sx:
                dx = -1
            elif ox <= sx:
                dx = 1
            if oy >= sy:
                dy = -1
            elif oy <= sy:
                dy = 1
            return [dx, dy]

    elif env == "resource_collection":
        resources = get_field("resources") or []
        if resources:
            best_res = min(resources, key=lambda item: abs(item[0] - sx) + abs(item[1] - sy))
            return move_toward(best_res[0], best_res[1])
        else:
            # No known resources, move toward opponent as heuristic
            return move_toward(ox, oy)

    # Default fallback move: stay or chase opponent
    return move_toward(ox, oy)

